#' Create a gif from the output of 3DCMCCFEM model
#'
#' \code{make_gif_3DFEM} use the output file generated by the function
#' \code{run_3DCMCCFEM} to create a gif of the simulation. In particular each frame
#' will correspond to one simulation year. For this reason this function works only with the annual output of the model.
#'
#' @param path Character: path to simulation output file. Must be annual.
#' @param years Numeric vector: years of simulations from which to create the
#'   gif
#' @param distribution Character: How tree should be distributed in the stand?.
#'   Options are c("regular","pseudorandom","random"). The pseudorandom option
#'   is the slowest but ensure a minimum distance among trees in the random distribution
#' @param outdir Character: path to the output directory.
#' @param return_gif Logical: Should a file gif be created? Default to TRUE.
#' @param delete_frame Logical: Should the single images frames be deleted after
#'   the creation of the gif file? Default to TRUE
#'
#' @details The function relys on \code{rgl::snapshot(...,top=TRUE)} so during
#'   the run it is a good idea to not alter the screen, to avoid
#'   \code{rgl::snapshot} capturing a wrong screenshot. The function became very
#'   slow when the number of tree to plot exeeds 300.
#'
#' @return Used for its side effects.It save in \code{outdir} as many images as
#'   the length of the simulation (if \code{delete_frame=FALSE}) and a gif file (if
#'   \code{return_gif=TRUE})
#' @seealso \code{\link{run_3DCMCCFEM}}
#' @export


make_gif_3DFEM <- function(path,years=NULL,distribution=c("regular","pseudorandom","random"),outdir,return_gif=TRUE,delete_frame=TRUE) {

  distribution <- match.arg(distribution,c("regular","pseudorandom","random"))

  for (p in c("rgl", "rLiDAR", "FNN", "magick")) {
    if (!requireNamespace(p, quietly = TRUE)) stop("Package '", p, "' is needed by make_gif_3DFEM")
  }
  dir.create(outdir,showWarnings = F,recursive = TRUE)
  stopifnot("Path must be the character path of an annual output of the 3D-CMCC-FEM model, as returned by run_3DCMCCFEM()"=check_char(path))
  stand <- utils::read.table(path, header = T, sep = ",")
  # the species column is SPECIE in 5.6 and SPECIES in 5.7 outputs
  colnames(stand)[grepl("^SPECIE", colnames(stand))] <- "SPECIE"

  if(!is.null(years)){
    stand <- stand[stand$YEAR%in%years,]
  }
  sim_years <- sort(unique(stand$YEAR))
  if (length(sim_years) < 2) stop("At least two years of simulation are needed")
  layers <- as.character(sort(unique(stand$LAYER)))

  crown <- c(Fagussylvatica="ellipsoid",
             Larixdecidua="cone",
             Piceaabies="cone",
             Pinussylvestris="cylinder",
             Quercusrobur="ellipsoid")

  draw_trees <- function(state, crw_typ) {
    for (i in seq_len(nrow(state))) {
      rLiDAR::LiDARForestStand(
        crownshape = crw_typ,
        CL = state$CL[i],
        CW = state$CW[i],
        HCB = state$HCB[i],
        X = state$x[i],
        Y = state$y[i],
        dbh = state$dbh[i] ,
        crowncolor = "forestgreen",
        stemcolor = "chocolate4",
        resolution = "low",
        mesh = F
      )
    }
  }
  save_frame <- function(year) {
    rgl::axes3d(c("x-", "x-", "y-", "z"), col = "black")
    rgl::title3d(main="3D-CMCC-FEM",sub = year,col="black")
    rgl::snapshot3d(file.path(outdir, paste0(year, ".png")),top=T,
                    webshot=F,width = 1000, height = 1000)
    rgl::close3d()
  }

  # initial state -----------------------------------------------------------

  withr::local_seed(4)
  rgl::par3d(windowRect=c(0,0,900,900))
  state <- list()
  crw <- list()

  for (l in layers) {

    l_stand <- stand[as.character(stand$LAYER)==l,]
    l_stand <- l_stand[order(l_stand$YEAR),]

    max_n <- max(l_stand$LIVETREE)
    message("Layer ",l,": ",nrow(l_stand), " years of simulation \nMax number of trees: ",max_n)

    crw[[l]] <- if(l_stand$SPECIE[1] %in% names(crown)) unname(crown[l_stand$SPECIE[1]]) else "ellipsoid"

    l_stand$HCB <- l_stand$HEIGHT-l_stand$CROWN_HEIGHT

    Ntrees <- l_stand$LIVETREE[1]
    meanHCB <- l_stand$HCB[1] # mean of the height at canopy base
    sdHCB <-    0.01*meanHCB # standard deviation of the height at canopy base
    HCB <- abs(stats::rnorm(Ntrees, mean = meanHCB, sd = abs(sdHCB)))# height at canopy base
    dbh <- FNN::knn.reg(y=l_stand$DBH,test=as.data.frame(HCB),train=l_stand$HCB, k=2)$pred/15
    CL <- FNN::knn.reg(y=l_stand$CROWN_HEIGHT,test=as.data.frame(HCB),train=l_stand$HCB, k=2)$pred*2
    CW <- FNN::knn.reg(y=l_stand$CROWN_DIAMETER,test=as.data.frame(HCB),train=l_stand$HCB, k=2)$pred/1.2

    if(distribution=="random"){
      grid <- data.frame(
        X = as.numeric(sample(1:100,Ntrees,replace = T)),
        Y = as.numeric(sample(1:100,Ntrees,replace = T))
      )
    }else if(distribution=="pseudorandom"){
      box <- sf::st_as_sfc(sf::st_bbox(c(xmin = 1, ymin = 1, xmax = 100, ymax = 100)))
      sampled_points <- .ssi_sample(box, Ntrees, r = sqrt(10000/max_n)/2)
      grid <- as.data.frame(sf::st_coordinates(sampled_points)[,1:2])
    }else{
      X <- seq(1,100,length.out=ceiling(sqrt(max_n)))
      Y <- seq(1,100,length.out=ceiling(sqrt(max_n)))
      grid <- expand.grid(X=X,Y=Y)
      grid <- grid[sample(seq_len(nrow(grid)),Ntrees),]
    }

    state[[l]] <- data.frame(HCB = HCB, CL = CL, CW = CW, dbh = dbh, x = grid$X, y = grid$Y)
    draw_trees(state[[l]], crw[[l]])
  }
  save_frame(sim_years[1])
  message("Saving initial state: Year ",sim_years[1])

  # following years ---------------------------------------------------------

  increment <- function(now, before, n) abs(stats::rnorm(n, mean = now - before, sd = abs(now - before)))

  for (j in 2:length(sim_years)) {

    rgl::par3d(windowRect=c(0,0,900,900))

    for (l in layers) {

      l_stand <- stand[as.character(stand$LAYER)==l,]
      now <- l_stand[l_stand$YEAR == sim_years[j],]
      before <- l_stand[l_stand$YEAR == sim_years[j - 1],]
      if (nrow(now) == 0 || nrow(before) == 0) next

      Ntrees <- min(now$LIVETREE[1], nrow(state[[l]]))
      st_l <- state[[l]][sample(seq_len(nrow(state[[l]])),Ntrees), ]

      st_l$HCB <- st_l$HCB + increment(now$HEIGHT, before$HEIGHT, Ntrees)
      st_l$CL <- st_l$CL + increment(now$CROWN_HEIGHT, before$CROWN_HEIGHT, Ntrees)
      st_l$CW <- st_l$CW + increment(now$CROWN_DIAMETER, before$CROWN_DIAMETER, Ntrees)
      st_l$dbh <- st_l$dbh + increment(now$DBH, before$DBH, Ntrees) / 15

      state[[l]] <- st_l
      draw_trees(st_l, crw[[l]])
    }
    save_frame(sim_years[j])
    message("Saving image: Year ",sim_years[j])
  }

  # make gif ----------------------------------------------------------------
  path_frame <- file.path(outdir, paste0(sim_years, ".png"))
  path_frame <- path_frame[file.exists(path_frame)]

  if(return_gif){
    img <- magick::image_read(path_frame)
    my.animation <- magick::image_animate(img, dispose = "previous",loop=1)
    magick::image_write(my.animation, file.path(outdir,paste0(tools::file_path_sans_ext(basename(path)),".gif")))
  }

  if(delete_frame){
    file.remove(path_frame)
  }
  invisible(path_frame)
}

# random points with a minimum distance r (simple sequential inhibition)
.ssi_sample <- function(box, n, r, max_try = 1000) {
  pts <- matrix(numeric(0), ncol = 2)
  bb <- sf::st_bbox(box)
  tries <- 0
  while (nrow(pts) < n && tries < max_try * n) {
    p <- c(stats::runif(1, bb["xmin"], bb["xmax"]), stats::runif(1, bb["ymin"], bb["ymax"]))
    if (nrow(pts) == 0 || min(sqrt((pts[, 1] - p[1])^2 + (pts[, 2] - p[2])^2)) >= r) pts <- rbind(pts, p)
    tries <- tries + 1
  }
  if (nrow(pts) < n) {
    warning("Only ", nrow(pts), " trees could be placed with the minimum distance; the others are placed randomly")
    extra <- cbind(stats::runif(n - nrow(pts), bb["xmin"], bb["xmax"]), stats::runif(n - nrow(pts), bb["ymin"], bb["ymax"]))
    pts <- rbind(pts, extra)
  }
  sf::st_as_sf(as.data.frame(pts), coords = 1:2)
}

